function getInquiryFormValue(form, name) {
  const field = form.elements.namedItem(name);
  if (field instanceof HTMLInputElement || field instanceof HTMLTextAreaElement) {
    return field.value.trim();
  }
  return "";
}
function buildWhatsappInquiryMessage(form) {
  const productTitle = document.querySelector(".pro-tit")?.innerText.trim();
  const fields = [
    ["姓名", getInquiryFormValue(form, "your-name")],
    ["邮箱", getInquiryFormValue(form, "your-email")],
    ["电话", getInquiryFormValue(form, "your-tel")],
    ["留言内容", getInquiryFormValue(form, "your-message")]
  ];
  const lines = ["网站留言咨询"];
  if (productTitle) {
    lines.push(`产品：${productTitle}`);
  }
  fields.forEach(([label, value]) => {
    if (value) {
      lines.push(`${label}：${value}`);
    }
  });
  return lines.join("\n");
}
